package calculator

import "testing"

func Add(a,b int)int{return a+b}

func TestAdd(t *testing.T){tests:=[]struct{name string;a,b,want int}{{"positive",2,3,5},{"negative",-2,1,-1},{"zero",0,0,0}};for _,tt:=range tests{t.Run(tt.name,func(t *testing.T){if got:=Add(tt.a,tt.b);got!=tt.want{t.Fatalf("Add(%d,%d)=%d; want %d",tt.a,tt.b,got,tt.want)}})}}
